import {representationForZoom} from './representation-scale.mjs';
import {planStorybookDressing,describeHexes} from './storybook-dressing-plan.mjs';
import {drawStorybookDressing} from './storybook-dressing-render.mjs';
import * as T from '../vendor/three.module.js';
// Presentation-only landmarks: no placement, physics or simulation writes.
export function cartoonLandmark(type){
 const group=new T.Group(),materials=new Map();
 const material=c=>{if(!materials.has(c))materials.set(c,new T.MeshStandardMaterial({color:c,roughness:1,flatShading:true}));return materials.get(c);};
 const mesh=(geo,c,x,y,z)=>{const m=new T.Mesh(geo,material(c));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;group.add(m);return m;};
 const box=(c,x,y,z,w,h,d)=>mesh(new T.BoxGeometry(w,h,d),c,x,y,z);
 const ball=(c,x,y,z,r)=>mesh(new T.IcosahedronGeometry(r,1),c,x,y,z);
 if(type==='ranch'||type==='sugar-shack'){
  box('#c86b48',0,.7,0,1.65,1.4,1.35);const roofShape=new T.Shape();roofShape.moveTo(-.98,0);roofShape.lineTo(0,.72);roofShape.lineTo(.98,0);roofShape.closePath();mesh(new T.ExtrudeGeometry(roofShape,{depth:1.6,bevelEnabled:false}),'#394d56',0,1.4,-.8);
  box('#fff1c9',0,.52,.687,.78,1.04,.06);box('#725743',0,.49,.73,.62,.92,.05);for(const angle of [-.58,.58]){const brace=box('#fff1c9',0,.49,.77,.055,1.08,.045);brace.rotation.z=angle;}mesh(new T.CylinderGeometry(.15,.15,.07,12),'#fff1c9',0,1.62,.84).rotation.x=Math.PI/2;for(const a of [-.57,.57])box('#fff1c9',a,1.0,.71,.25,.34,.08);mesh(new T.CylinderGeometry(.35,.35,1.9,12),'#d8e0d0',1,.95,-.2);mesh(new T.ConeGeometry(.41,.34,8),'#677a7c',1,2.07,-.2);
  group.userData.landmark='Barn and silo';
 }else if(type==='paddock'){
  box('#f5ead5',0,.85,0,1.35,.8,.72);box('#f5ead5',.78,1.07,.05,.65,.72,.62);box('#dfb09c',1.06,.9,.05,.26,.3,.64);for(const x of [-.48,.48])for(const z of [-.24,.24])box('#57483e',x,.3,z,.18,.6,.18);box('#54473b',-.25,1.26,0,.5,.05,.5);for(const z of [-.34,.34])ball('#a58f70',.72,1.45,z,.12);for(const z of [-.32,.32])ball('#242d30',1.05,1.2,z,.055);group.userData.landmark='Grazing cow';
 }else if(type==='crop'){
  for(let row=0;row<3;row++){box('#856246',0,.08,(row-1)*.62,2.05,.16,.43);for(let col=0;col<3;col++){const x=(col-1)*.62,z=(row-1)*.62;ball('#779347',x,.36,z,.27);ball('#a7b965',x+.08,.46,z,.2);}}group.userData.landmark='Kitchen garden';
 }else if(type==='meadow'){group.userData.landmark='Wildflower meadow';
 }else if(type==='moon'){
  mesh(new T.SphereGeometry(.95,14,7,0,Math.PI*2,0,Math.PI/2),'#eef1f4',0,0,0);mesh(new T.CylinderGeometry(1,1,.12,14),'#7f8a99',0,.06,0);box('#5d6b85',0,.32,.92,.5,.62,.4);box('#ffd36a',0,.42,1.13,.26,.3,.04);
  for(const a of [0,1.05,2.1])box('#9fb3c9',Math.sin(a)*.5,.62+Math.cos(a)*.12,Math.cos(a)*.5-.05,.16,.16,.04).lookAt(0,1.4,0);
  box('#b9c0cc',-1.25,.55,-.25,.08,1.1,.08);const dish=mesh(new T.ConeGeometry(.3,.16,12,1,true),'#e6e9ef',-1.25,1.16,-.25);dish.rotation.x=-.7;dish.material.side=T.DoubleSide;ball('#ff7a5a',-1.25,1.32,-.25,.06);
  const panel=box('#2f4f9a',1.35,.5,.25,.85,.05,.55);panel.rotation.z=-.45;box('#b9c0cc',1.3,.24,.25,.06,.48,.06);
  group.userData.landmark='Moon dome';
 }else return null;
 group.userData.representationOnly=true;return group;
}
export function createCartoonLayer(active,{meadowsOnly=false}={}){
 const root=new T.Group();root.name='Cartoon representation';root.userData.representationOnly=true;const hidden=[],supported=[],unsupported=[];
 for(const tile of active.tileObjects||[]){const plan=active.assembly.plans.find(p=>p.id===tile.id);if(!plan||(meadowsOnly&&plan.type!=='meadow'))continue;const landmark=cartoonLandmark(plan.type);if(!landmark){unsupported.push(tile.id);continue;}const diameter=active.config?.size||100;const scale=diameter*.1*.21;landmark.scale.setScalar(scale);landmark.position.set(tile.object.position.x,active.heightAt(plan.center.x,plan.center.z)*.1+.05,tile.object.position.z);root.add(landmark);const dressing=planStorybookDressing({seed:active.recipe.seed,id:tile.id,type:plan.type,diameter,paths:plan.paths||[]});root.add(drawStorybookDressing(dressing,plan,active.heightAt));supported.push({id:tile.id,type:plan.type,landmark:landmark.userData.landmark,dressing:{seed:dressing.seed,habitat:dressing.habitatName,waterBodies:dressing.patches?.filter(p=>p.kind==='water').length||0,features:dressing.features,items:dressing.items.length,scope:'Seeded visual dressing; not an ecology simulation'}});for(const child of tile.object.children){if(child.userData.motionKey||child.userData.gardenItemId){hidden.push([child,child.visible]);child.visible=false;}}}
 active.group.add(root);return {supported,unsupported,dispose(){for(const [o,visible]of hidden)o.visible=visible;root.removeFromParent();const materials=new Set();root.traverse(o=>{o.geometry?.dispose();if(o.material)materials.add(o.material);});for(const m of materials)m.dispose();}};
}
export function installDeveloperMode({getActive,getFamily,isBusy,render,icon,camera,orbit,getZoomCoverage=()=>NaN}){
 let automatic=true,enabled=false,cartoon=false,annotations=false,shiftHeld=false,panelOpen=true,revision=0,layer=null,owner=null,ownerTileCount=-1;try{automatic=localStorage.getItem('sandbox-zoom-compensated-detail')!=='false';enabled=localStorage.getItem('sandbox-developer')==='true';cartoon=localStorage.getItem('sandbox-cartoon')==='true';}catch{}
 const button=document.createElement('button');button.id='developer-toggle';button.title='Developer mode';button.setAttribute('aria-label','Developer mode');button.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16"/></svg>';document.querySelector('#toolbar-tools').append(button);
 const panel=document.createElement('aside');panel.id='developer-overlay';panel.hidden=!enabled;panel.setAttribute('aria-label','Developer overlay');panel.innerHTML='<div class="developer-heading"><strong>Developer mode</strong><button id="developer-close" aria-label="Hide developer overlay">×</button></div><label class="developer-switch"><span>Developer mode</span><input id="developer-enabled" type="checkbox"></label><label class="developer-switch"><span>Zoom-compensated detail</span><input id="developer-auto" type="checkbox"></label><label class="developer-switch"><span>Comic mode</span><input id="developer-cartoon" type="checkbox"></label><label class="developer-switch"><span>Hex annotations · hold Shift</span><input id="developer-annotations" type="checkbox"></label><p id="developer-mode-status"></p><dl id="developer-facts"></dl><div id="developer-warnings"></div><section id="developer-hexes" aria-label="Hex inventory"></section>';document.body.append(panel);
 const labels=document.createElement('div');labels.id='hex-annotations';labels.setAttribute('aria-label','Hex annotations');document.body.append(labels);
 window.addEventListener('keydown',event=>{if(event.key==='Shift'&&!event.target?.closest?.('input,textarea,[contenteditable=true]'))shiftHeld=true;});window.addEventListener('keyup',event=>{if(event.key==='Shift')shiftHeld=false;});window.addEventListener('blur',()=>{shiftHeld=false;});document.addEventListener('visibilitychange',()=>{if(document.hidden)shiftHeld=false;});
 const autoToggle=panel.querySelector('#developer-auto');
 const annotationToggle=panel.querySelector('#developer-annotations');
 const toggle=panel.querySelector('#developer-cartoon'),enabledToggle=panel.querySelector('#developer-enabled');
 const read=()=>({revision,enabled,open:enabled&&panelOpen,cartoon,automatic,zoomCompensatedDetail:automatic,granularity:cartoon?'place':'scene',zoomCoverage:getZoomCoverage(),annotations,annotationsVisible:(enabled&&annotations)||shiftHeld,hexes:describeHexes(getActive()),available:getFamily()==='ranch',seed:getActive()?.recipe?.seed,tiles:getActive()?.recipe?.tiles?.length||0,landmarks:layer?.supported||[],unsupportedTiles:layer?.unsupported||[],warnings:getActive()?.assembly?.plans?.flatMap(p=>(p.warnings||[]).map(w=>({tileId:p.id,message:w})))||[]});
 function refresh(){const state=read();button.setAttribute('aria-pressed',String(enabled));panel.hidden=!enabled||!panelOpen;enabledToggle.checked=enabled;toggle.checked=cartoon;autoToggle.checked=automatic;annotationToggle.checked=annotations;toggle.disabled=getFamily()!=='ranch'||isBusy();panel.querySelector('#developer-mode-status').textContent=getFamily()!=='ranch'?'Comic mode is available on farm boards.':(automatic?'Zoom compensated · ':'Manual · ')+(cartoon?'Comic view':'Detailed scene');const facts=panel.querySelector('#developer-facts');facts.replaceChildren();for(const [name,value]of [['Seed',state.seed??'—'],['Hexes',state.tiles],['Landmarks',state.landmarks.length],['Site warnings',state.warnings.length]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;facts.append(dt,dd);}panel.querySelector('#developer-warnings').textContent=state.unsupportedTiles.length?`${state.unsupportedTiles.length} special hexes retain their original representation.`:'';}
 function apply(){const active=getActive();if(layer){layer.dispose();layer=null;}owner=active;ownerTileCount=active?.tileObjects?.length||0;if(getFamily()==='ranch'&&active?.tileObjects)layer=createCartoonLayer(active,{meadowsOnly:!cartoon});refresh();rebuildAnnotations();render();}
 function set({developer=enabled,representation=cartoon,showAnnotations=annotations,followZoom=automatic}){if(isBusy())throw Error('Wait for the scene interaction to finish.');if(representation&&getFamily()!=='ranch')throw Error('Cartoon representation requires a farm board.');if(developer&&!enabled)panelOpen=true;automatic=followZoom;enabled=developer;annotations=showAnnotations;cartoon=automatic&&getFamily()==='ranch'?representationForZoom(getZoomCoverage(),representation):representation;revision++;try{localStorage.setItem('sandbox-zoom-compensated-detail',String(automatic));localStorage.setItem('sandbox-developer',String(enabled));localStorage.setItem('sandbox-cartoon',String(cartoon));}catch{}apply();window.RanchView?.changed('Developer visualization');return {state:read()};}
 button.onclick=()=>{if(!enabled)set({developer:true});else{panelOpen=!panelOpen;refresh();}};panel.querySelector('#developer-close').onclick=()=>{panelOpen=false;refresh();};enabledToggle.onchange=()=>set({developer:enabledToggle.checked,representation:cartoon});autoToggle.onchange=()=>set({followZoom:autoToggle.checked});toggle.onchange=()=>set({representation:toggle.checked,followZoom:false});annotationToggle.onchange=()=>set({showAnnotations:annotationToggle.checked});
 let labelRecords=[],annotationKey='';
 function rebuildAnnotations(){const hexes=describeHexes(getActive());labels.replaceChildren();const inventory=panel.querySelector('#developer-hexes');inventory.replaceChildren();labelRecords=hexes.filter(h=>h.center).map(h=>{const element=document.createElement('span');element.className='hex-caption';const number=document.createElement('b'),name=document.createElement('span');number.textContent=String(h.number).padStart(2,'0');name.textContent=h.name;element.append(number,name);element.title=h.name+' · '+h.purpose;labels.append(element);const row=document.createElement('article'),title=document.createElement('strong'),description=document.createElement('p'),meta=document.createElement('small');title.textContent=String(h.number).padStart(2,'0')+' · '+h.name;const decoration=layer?.supported.find(t=>t.id===h.id)?.dressing;description.textContent=h.purpose+(decoration?' · '+decoration.features.join(' · '):'');meta.textContent=h.id+' · Seed '+h.seed+(h.q!==null?' · Hex '+h.q+', '+h.r:'')+(h.neighbors.length?' · Neighbors: '+h.neighbors.join(', '):'');row.append(title,description,meta);inventory.append(row);return {element,name,hex:h};});annotationKey=JSON.stringify(hexes);}
 function positionAnnotations(){if(automatic&&getFamily()==='ranch'&&!isBusy()){const next=representationForZoom(getZoomCoverage(),cartoon);if(next!==cartoon){cartoon=next;revision++;apply();window.RanchView?.changed('Zoom representation');}}labels.hidden=!((enabled&&annotations)||shiftHeld);const active=getActive();if(!labels.hidden&&active){if(annotationKey!==JSON.stringify(describeHexes(active)))rebuildAnnotations();const used=[];for(const record of labelRecords){const h=record.hex,diameter=active.config?.size||100,x=h.center.x,z=h.center.z+diameter*.35,p=new T.Vector3(x*.1,active.heightAt?.(x,z)*.1+.08||.08,z*.1).project(camera),sx=(p.x*.5+.5)*innerWidth,sy=(-p.y*.5+.5)*innerHeight;record.element.hidden=p.z>1||p.z< -1||sx<0||sx>innerWidth||sy<64||sy>innerHeight-70;if(record.element.hidden)continue;const crowded=used.some(q=>Math.abs(q.x-sx)<145&&Math.abs(q.y-sy)<32);record.name.hidden=crowded;record.element.style.transform=`translate(${sx}px,${sy}px) translate(-50%,-50%)`;used.push({x:sx,y:sy});}}requestAnimationFrame(positionAnnotations);}
 rebuildAnnotations();requestAnimationFrame(positionAnnotations);
 setInterval(()=>{if(!isBusy()&&(getActive()!==owner||(getActive()?.tileObjects?.length||0)!==ownerTileCount))apply();else if(enabled)refresh();},600);
 const paths={ai:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/><path d="m19 2 .8 2.2L22 5l-2.2.8L19 8l-.8-2.2L16 5l2.2-.8Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--app-paper,#fffcf0)"/><circle cx="15" cy="17" r="3" fill="var(--app-paper,#fffcf0)"/>'};
 function polish(){for(const [selector,path]of [['#ai-composer-toggle',paths.ai],['#app-settings-toggle',paths.settings],['#app-jukebox-toggle','<path d="M9 17V6l10-2v11M9 10l10-2"/><ellipse cx="6" cy="17" rx="3" ry="2"/><ellipse cx="16" cy="15" rx="3" ry="2"/>']]){const b=document.querySelector(selector);if(b&&!b.dataset.polished){b.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;b.dataset.polished='true';}}}polish();setTimeout(polish,2000);
 window.RanchView?.register('sandboxDeveloper',read,render);window.RanchActions?.register('sandboxDeveloper',{read,revision:()=>revision,unavailable:()=>isBusy()?'Scene is busy':null,actions:{set:{description:'Set developer overlay and cartoon farm representation',schema:{type:'object',properties:{developer:{type:'boolean'},representation:{type:'boolean'},showAnnotations:{type:'boolean'},followZoom:{type:'boolean'}},required:['developer','representation'],additionalProperties:false},run:set}}});refresh();return {read};
}
